"use client"

import { useState } from "react"
import { FlowShell } from "../_shared/FlowShell"
import { TabsRoot, TabsList, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import {
  ListItem,
  ListItemContent,
  ListItemTitle,
  ListItemDescription,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { FolderOpen, SearchX, Search } from "lucide-react"
import { EmptyState } from "./EmptyState"

type Scenario = "list" | "first-use" | "no-results"

const PROJECTS = [
  { id: "p1", name: "Website redesign", updated: "Updated 6 Oct 2026" },
  { id: "p2", name: "Mobile app launch", updated: "Updated 2 Oct 2026" },
  { id: "p3", name: "Q4 planning", updated: "Updated 27 Sep 2026" },
]

const NO_MATCH_QUERY = "Zebra"

export default function EmptyStatePage() {
  const [scenario, setScenario] = useState<Scenario>("list")
  const [query, setQuery] = useState("")

  const changeScenario = (value: string) => {
    const next = value as Scenario
    setScenario(next)
    setQuery(next === "no-results" ? NO_MATCH_QUERY : "")
  }

  const onSearch = (value: string) => {
    setQuery(value)
    if (scenario === "first-use") return
    setScenario(value && !matches(value) ? "no-results" : "list")
  }

  const clearSearch = () => {
    setQuery("")
    setScenario("list")
  }

  const projects = scenario === "first-use" ? [] : PROJECTS.filter((p) => nameMatches(p.name, query))
  const firstUse = scenario === "first-use"
  const noResults = !firstUse && projects.length === 0

  return (
    <FlowShell
      title="Projects empty state"
      step={0}
      totalSteps={1}
      showProgress={false}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockEnd: "var(--atlas-spacing-6)",
        }}
      >
        <TabsRoot variant="segmented" size="sm" value={scenario} onValueChange={changeScenario}>
          <TabsList aria-label="Preview state">
            <TabsTrigger value="list">List</TabsTrigger>
            <TabsTrigger value="first-use">First use</TabsTrigger>
            <TabsTrigger value="no-results">No results</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-text-h1)",
            fontWeight: "var(--atlas-font-weight-bold)",
            lineHeight: "var(--atlas-line-height-tight)",
            color: "var(--atlas-foreground)",
          }}
        >
          Projects
        </h1>

        <Input
          type="search"
          size="md"
          aria-label="Search projects"
          placeholder="Search projects"
          leadingIcon={<Search size={16} aria-hidden="true" />}
          value={query}
          disabled={firstUse}
          onChange={(e) => onSearch(e.target.value)}
        />

        {firstUse && (
          <EmptyState
            icon={<FolderOpen size={24} aria-hidden="true" />}
            title="No projects yet"
            description="Projects keep related files, tasks and people in one place. Create your first project to get started."
            action={
              <Button variant="primary" size="lg" onClick={() => changeScenario("list")}>
                Create project
              </Button>
            }
          />
        )}

        {noResults && (
          <EmptyState
            icon={<SearchX size={24} aria-hidden="true" />}
            title="No results"
            description={`No projects match “${query}”. Check the spelling or try a different search.`}
            action={
              <Button variant="outline" size="lg" onClick={clearSearch}>
                Back to all projects
              </Button>
            }
          />
        )}

        {!firstUse && !noResults && (
          <ul
            aria-label="Projects"
            style={{
              listStyle: "none",
              margin: 0,
              padding: 0,
              display: "flex",
              flexDirection: "column",
              gap: "var(--atlas-spacing-2)",
            }}
          >
            {projects.map((p) => (
              <ListItem key={p.id} as="li" variant="outline" size="md">
                <ListItemContent>
                  <ListItemTitle>{p.name}</ListItemTitle>
                  <ListItemDescription>{p.updated}</ListItemDescription>
                </ListItemContent>
              </ListItem>
            ))}
          </ul>
        )}
      </div>
    </FlowShell>
  )
}

function nameMatches(name: string, query: string) {
  return name.toLowerCase().includes(query.trim().toLowerCase())
}

function matches(query: string) {
  return PROJECTS.some((p) => nameMatches(p.name, query))
}

